"""Prototype walking right: alternate original foot layers, gaze right, digital animation."""
from pathlib import Path
from PIL import Image,ImageDraw
import numpy as np,math,io,cairosvg,base64,json
root=Path(__file__).resolve().parents[1];base=Image.open(root/'assets/mascot/spark.png').convert('RGBA');src=Image.open(root/'assets/mascot/look/right_3.png').convert('RGBA');w,h=base.size;Y,X=np.indices((h,w))
edge=np.interp(np.arange(h),[300,310,320,330,340,350,360,370,380,390,400,410,420,430,440,450,460,470,480,490,500],[64,63,62,62,62,62,62,64,65,67,70,73,77,82,87,93,101,110,120,132,145])[:,None];cut=(Y>=315)&(Y<490)&((X>545-edge)|(X<edge));boundary=np.interp(np.arange(w),[0,70,100,130,160,190,230,273,316,356,386,416,446,476,546],[330,430,468,491,506,516,526,531,526,516,506,491,468,430,330])[None,:];zones=[(X>130)&(X<260),(X>286)&(X<416)];feet=[];original=np.array(base)
for j,z in enumerate(zones):
 f=original.copy();f[:,:,3]=np.where(z&(Y>boundary+5),f[:,:,3],0);back=Image.new('RGBA',(w,h));d=ImageDraw.Draw(back);points=[(150,475),(250,490),(250,557),(161,548)] if j==0 else [(296,490),(396,475),(385,548),(296,557)];d.polygon(points,fill=(139,158,120,255));d.line([points[0],points[3]],fill=(91,46,31,255),width=8);d.line([points[1],points[2]],fill=(91,46,31,255),width=8);back.alpha_composite(Image.fromarray(f));feet.append(back)
a=np.array(src).copy();a[:,:,3]=np.where(cut|((zones[0]|zones[1])&(Y>boundary)),0,a[:,:,3]);body=Image.fromarray(a)
svg='''<svg xmlns="http://www.w3.org/2000/svg" width="546" height="546"><defs><linearGradient id="g" x1="0" y1="0" x2=".85" y2="1"><stop stop-color="#e7a064"/><stop offset=".53" stop-color="#c09265"/><stop offset="1" stop-color="#8d9970"/></linearGradient></defs><path d="M480 320 C494 325 508 346 518 368 C530 394 536 417 532 440 C529 463 514 477 497 476 C480 475 469 465 465 448 C460 425 461 394 463 370 C465 345 468 328 480 320 Z" fill="url(#g)" stroke="#5d2c20" stroke-width="10" stroke-linejoin="round"/><path d="M496 439 C496 454 508 459 516 448" fill="none" stroke="#925a3e" stroke-width="6" stroke-linecap="round"/><path d="M510 363 C516 381 518 397 519 411" fill="none" stroke="#f1ba80" stroke-width="7" stroke-linecap="round" opacity=".65"/></svg>'''
arm=Image.open(io.BytesIO(cairosvg.svg2png(bytestring=svg.encode()))).convert('RGBA');folder=root/'animation_lab/walk_right';folder.mkdir(exist_ok=True);frames=[]
for i in range(32):
 t=2*math.pi*i/32;c=Image.new('RGBA',(806,730));
 for j,foot in enumerate(feet):
  phase=t+j*math.pi;dx=round(19*math.cos(phase));lift=round(11*max(0,math.sin(phase)));layer=Image.new('RGBA',(806,730));layer.alpha_composite(foot,(130,65));c.alpha_composite(layer,(dx,-lift))
 y=-round(2*(1-math.cos(2*t)));c.alpha_composite(arm,(130,65+y));c.alpha_composite(arm.transpose(Image.Transpose.FLIP_LEFT_RIGHT),(130,65+y));c.alpha_composite(body,(130,65+y));c.thumbnail((260,253),Image.Resampling.LANCZOS);p=folder/f'frame_{i:02}.png';c.save(p,optimize=True);frames.append('data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode())
html='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مشي سبارك لليمين</title><style>*{box-sizing:border-box}body{margin:0;min-height:100svh;display:grid;place-items:center;padding:20px;background:#fbf6ef;color:#382b26;font-family:system-ui,sans-serif}.card{width:min(100%,650px);background:white;border:1px solid #f0e3d6;border-radius:28px;padding:26px;text-align:center;box-shadow:0 12px 35px #8a563315}.badge{display:inline-block;border-radius:99px;background:#fff0e3;color:#b3582d;padding:7px 14px;font-size:13px;font-weight:bold}h1{font-size:24px}p{line-height:1.8;color:#756158}.stage{position:relative;height:290px;overflow:hidden;background:#fffaf5;border-radius:20px}.floor{position:absolute;bottom:48px;left:8%;right:8%;height:2px;background:#e9d8c8}img{position:absolute;bottom:12px;left:0;width:210px;height:204px;object-fit:contain}button{border:0;border-radius:99px;background:#bd603a;color:white;font:700 16px system-ui;padding:13px 25px;cursor:pointer;margin-top:18px}button:focus-visible{outline:3px solid #916541;outline-offset:3px}.note{font-size:13px}</style><main class="card"><span class="badge">تجربة منفصلة • مش داخل التطبيق</span><h1>سبارك تمشي لليمين 🐾</h1><p>تشوف لليمين، وتبدّل بين رجليها وهي تتحرك.</p><div class="stage" id="stage"><div class="floor"></div><img id="pet" alt="سبارك تنظر لليمين وتمشي بخطوات متبادلة"></div><button id="replay">شغّلي المشية من جديد ↻</button><p class="note">تجربة رقمية باستخدام طبقتين منفصلتين للرجلين؛ نراجع المشية مع بعض قبل الاعتماد 💛</p></main><script>const frames=FRAMES;const img=document.getElementById('pet'),stage=document.getElementById('stage');let token=0;function run(){const id=++token,start=performance.now(),duration=4800;function tick(now){if(id!==token)return;const t=Math.min((now-start)/duration,1);img.src=frames[Math.floor(t*4*32)%32];img.style.transform=`translateX(${Math.max(0,stage.clientWidth-210)*t}px)`;if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}document.getElementById('replay').onclick=run;if(matchMedia('(prefers-reduced-motion: reduce)').matches){img.src=frames[0]}else run();</script></html>'''.replace('FRAMES',json.dumps(frames));(root/'web_extra/spark-walk-right-preview.html').write_text(html,encoding='utf8')
